// SIAARA DICOM Toolkit - character sets (Specific Character Set, PS3.3 C.12.1.1.2; PS3.5 6.1,
// Annexes H/I/J/K; ISO/IEC 2022 code extension as profiled by DICOM).
//
// Decodes text values to UTF-8 and encodes UTF-8 back to a data set's character set. Written
// from the standards; the conversion tables are generated by tools/gen_charsets.py from the
// Unicode Consortium and WHATWG mapping files. No exceptions are thrown other than
// std::bad_alloc from std::string growth; every read is bounds-checked.
#pragma once

#include <cstddef>
#include <cstdint>
#include <optional>
#include <string>
#include <string_view>
#include <vector>

#include "core/dataset.hpp"
#include "core/status.hpp"
#include "core/types.hpp"

namespace siaara::charset {

// Defined terms of (0008,0005). Each term covers both its "ISO_IR nnn" and "ISO 2022 IR nnn" form.
enum class Term : std::uint8_t {
    IR6,      // default repertoire (ASCII); value 1 empty
    IR100,    // Latin alphabet No. 1 (ISO 8859-1)
    IR101,    // Latin-2 (8859-2)
    IR109,    // Latin-3 (8859-3)
    IR110,    // Latin-4 (8859-4)
    IR144,    // Cyrillic (8859-5)
    IR127,    // Arabic (8859-6)
    IR126,    // Greek (8859-7)
    IR138,    // Hebrew (8859-8)
    IR148,    // Latin-5 (8859-9)
    IR203,    // Latin-9 (8859-15)
    IR13,     // JIS X 0201: G0 Romaji (ISO-IR 14), G1 Katakana (ISO-IR 13)
    IR166,    // Thai, TIS 620-2533 (8859-11)
    IR87,     // JIS X 0208 (ISO 2022 only, G0)
    IR159,    // JIS X 0212 (ISO 2022 only, G0)
    IR149,    // KS X 1001 (ISO 2022 only, G1)
    IR58,     // GB 2312 (ISO 2022 only, G1)
    IR192,    // UTF-8 (no code extensions)
    GB18030,  // GB 18030 (no code extensions)
    GBK,      // GBK (no code extensions)
};

enum class Scheme : std::uint8_t { Iso2022, Utf8, Gb18030, Gbk };

// A parsed Specific Character Set value.
struct CharacterSet {
    Scheme scheme = Scheme::Iso2022;
    std::vector<Term> terms{Term::IR6};  // terms[0] is value 1 (IR6 when value 1 is empty)
    bool extensions = false;   // ISO 2022 code extension in use (multi-valued or "ISO 2022" form)
    std::size_t unknown = 0;   // values not recognised (ignored; they never stop decoding)
    std::size_t lenient = 0;   // values recognised only after normalising spelling/spacing

    // Parses the raw (0008,0005) value (backslash separated, padding allowed). Never fails:
    // unknown values are counted and skipped; an empty value means the default repertoire.
    static CharacterSet parse(std::string_view specific_character_set);
    // Canonical (0008,0005) text, e.g. "\ISO 2022 IR 87" or "ISO_IR 100".
    std::string to_string() const;
};

// How delimiters reset the ISO 2022 state (PS3.5 6.1.2.5.3) and how values split.
enum class TextKind : std::uint8_t {
    Text,          // ST, LT, UT, UR: CR, LF, FF and TAB are delimiters; no value multiplicity
    MultiValued,   // SH, LO, UC and other string VRs: also backslash
    PersonName,    // PN: also '^' and '='
};
TextKind text_kind(VR vr) noexcept;
// True for the VRs whose values (0008,0005) applies to: SH, LO, UC, ST, LT, UT, PN.
bool vr_uses_character_set(VR vr) noexcept;

// Decodes `bytes` to UTF-8. Undecodable bytes, unknown or malformed escape sequences and
// truncated multi-byte characters become U+FFFD; `replacements` (optional) receives their count.
// Delimiters always come out as their ASCII characters, and no other input ever decodes to an
// ASCII delimiter, so the result can be split on '\\', '^' and '='.
std::string decode(std::string_view bytes, const CharacterSet& cs, TextKind kind,
                   std::size_t* replacements = nullptr);

struct Unrepresentable {
    char32_t code_point;    // U+FFFD for malformed UTF-8 input
    std::size_t offset;     // byte offset in the UTF-8 input
};
struct EncodeResult {
    std::string bytes;                       // characters that failed are written as '?'
    std::vector<Unrepresentable> failures;   // empty on success
    bool ok() const noexcept { return failures.empty(); }
};
// Encodes UTF-8 text in `cs`. With code extensions, escape sequences are chosen from the
// listed terms (current set first, then value 1, then the others in order) and the value 1
// state is restored before every delimiter and at the end, as PS3.5 6.1.2.5.3 requires.
EncodeResult encode(std::string_view utf8, const CharacterSet& cs, TextKind kind);

// ---- data set helpers
// The character set in force for `ds`: its own (0008,0005) if present, else `inherited`
// (the enclosing data set's, for sequence items), else the value the item carries from the
// enclosing data set (Dataset::inherited_charset, F15), else the default repertoire.
CharacterSet character_set_of(const Dataset& ds, const CharacterSet* inherited = nullptr);

// Value `vm` (0-based) of a text element as UTF-8, padding removed like Dataset::get_string.
// VRs that (0008,0005) does not apply to are decoded with the default repertoire; binary VRs
// fall back to Dataset::get_string. nullopt when absent, a sequence, or vm is out of range.
std::optional<std::string> get_utf8(const Dataset& ds, Tag tag, std::size_t vm = 0,
                                    const CharacterSet* inherited = nullptr);

// Encodes `utf8` (all values, backslash separated) into the data set's character set and
// stores it. Fails with Errc::Unsupported, leaving the data set unchanged, if any character
// cannot be represented. `failures` (optional) receives the details.
Status set_utf8(Dataset& ds, Tag tag, VR vr, std::string_view utf8,
                const CharacterSet* inherited = nullptr,
                std::vector<Unrepresentable>* failures = nullptr);

// PN value split into component groups (alphabetic, ideographic, phonetic; PS3.5 6.2.1) and
// their five components (family, given, middle, prefix, suffix). Input is decoded UTF-8.
struct PersonName {
    std::string groups[3];
    std::string components[3][5];
};
PersonName split_person_name(std::string_view utf8_value);

// Size in bytes of the generated conversion tables linked into the library.
std::size_t table_bytes() noexcept;

}  // namespace siaara::charset
